use nms_core::{address::GalacticAddress,biome::Biome,system::{System,Planet},player::{PlayerBase,BaseType}};
use nms_graph::{GalaxyModel,SystemId,GraphError};
use nms_graph::{query::BiomeFilter,route::{Route,RouteHop,RouteError,RoutingAlgorithm}};
use nms_query::route::{RouteFrom,RouteQuery,TargetSelection,execute_route};
fn id(a:GalacticAddress)->SystemId{SystemId::from_address(&a)}
fn main(){
 let mut m=GalaxyModel::new();
 let a=GalacticAddress::new(0,0,0,100,0,9);let b=GalacticAddress::new(1,0,0,101,0,9);let c=GalacticAddress::new(2,0,0,102,0,9);let z=GalacticAddress::new(0,0,0,100,0,0);
 for address in [a,b,c,z]{m.insert_system(System::new(address,None,None,None,vec![Planet::new(1,Some(Biome::Lush),None,false,None,None)]));}
 println!("cross_shortest={:?}",m.shortest_path(id(z),id(a)).unwrap_err());
 let r=Route{hops:vec![RouteHop{system_id:id(a),leg_distance_ly:55.0,cumulative_ly:99.0,is_waypoint:false},RouteHop{system_id:id(c),leg_distance_ly:1.0,cumulative_ly:1.0,is_waypoint:true}],total_distance_ly:1.0};
 let actual=m.constrain_hops(&r,400.0).unwrap();
 println!("normalized_route={:?} total={}",actual.hops.iter().map(|h|(h.leg_distance_ly,h.cumulative_ly,h.is_waypoint)).collect::<Vec<_>>(),actual.total_distance_ly);
 let key=(id(a),1); let view=m.nearest_planets_from_address(&a,1,&BiomeFilter::default());
 println!("canonical_planet_borrow={}",std::ptr::eq(view[0].1,&m.planets[&key]));
 let missing=GalacticAddress::new(50,0,0,1,0,9);
 m.insert_base(PlayerBase::new("Foreign".into(),BaseType::HomePlanetBase,z,[0.;3],None));
 m.insert_base(PlayerBase::new("Missing".into(),BaseType::HomePlanetBase,missing,[0.;3],None));
 let q=RouteQuery{targets:TargetSelection::Named(vec!["Foreign".into(),"Missing".into()]),from:RouteFrom::Address(a),warp_range:None,within_ly:None,max_targets:Some(0),algorithm:RoutingAlgorithm::NearestNeighbor,return_to_start:false};
 let error=execute_route(&m,&q).unwrap_err(); println!("named_membership_precedence={:?}",error.downcast_ref::<RouteError>());
 println!("empty_galaxy_display={}",GraphError::NoSystemsInGalaxy(7));
 println!("missing_name_display={}",GraphError::TargetNotFound("Absent".into()));
}

