use nms_core::address::GalacticAddress;
use nms_graph::{GalaxyModel,SystemId,query::BiomeFilter,route::RoutingAlgorithm};
use nms_query::route::{RouteQuery,RouteFrom,TargetSelection,execute_route};
fn main(){
 let save=nms_save::parse_save_file(std::path::Path::new("/private/tmp/nms-s08-cdc-review/single-target.json")).unwrap();let model=GalaxyModel::from_save(&save);
 let start=SystemId::from_address(&GalacticAddress::new(-896,0,0,32,0,0));let target=SystemId::from_address(&GalacticAddress::new(100,0,0,16,0,0));
 for algorithm in [RoutingAlgorithm::NearestNeighbor,RoutingAlgorithm::TwoOpt]{
 let r=execute_route(&model,&RouteQuery{targets:TargetSelection::Biome(BiomeFilter{biome:Some(nms_core::biome::Biome::Lush),..Default::default()}),from:RouteFrom::CurrentPosition,warp_range:None,within_ly:None,max_targets:None,algorithm,return_to_start:true}).unwrap();
 assert_eq!(r.route.hops.iter().map(|h|h.system_id).collect::<Vec<_>>(),vec![start,target,start]);assert_eq!(r.route.hops.iter().map(|h|h.leg_distance_ly).collect::<Vec<_>>(),vec![0.0,398400.0,398400.0]);assert_eq!(r.route.total_distance_ly,796800.0);assert_eq!(r.targets_visited,1);
 println!("{algorithm:?}: exact start/target/start and legs0/398400/398400, total796800, count1");
 }
}

